+    // else — including EBADF, reported on macOS Node 22 in issue #3264 — is
+    // thrown from ChildProcess.spawn. Without this guard the throw escapes
+    // the setTimeout callback and crashes the CLI as uncaughtException.
+    let child: ChildProcess;
+    try {
+      child = exec(
+        cmd,
+        { cwd: cfg.getTargetDir(), timeout: 5000, maxBuffer: 1024 * 10 },
+        (error, stdout) => {
+          if (gen !== generationRef.current) return; // stale
+          activeChildRef.current = undefined;
+          if (!error && stdout) {
+            // Strip only the trailing newline to preserve intentional whitespace.
+            const line = stdout.replace(/\r?\n$/, '').split(/\r?\n/, 1)[0];
+            setOutput(line || null);
+          } else {
+            setOutput(null);
+          }
+        },
+      );
+    } catch (err) {
+      debugLog.error('statusline exec error:', (err as Error).message);
+      setOutput(null);
+      return;
+    }

     activeChildRef.current = child;

log_parser:
def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def normalize_status(raw: str | None) -> str | None:
        if not raw:
            return None
        status = raw.strip().lower()
        if status in {"passed", "pass", "ok", "success"}:
            return "pass"
        if status in {"failed", "fail", "error", "errors", "timeout"}:
            return "fail"
        if status in {"skipped", "skip", "pending", "todo", "disabled", "canceled", "cancelled", "ignored"}:
            return "skip"
        if status in {"xfailed"}:
            return "skip"
        if status in {"xpassed"}:
            return "fail"
        return None

    def add_result(name: str, status: str) -> None:
        if not name:
            return
        if name in results:
            # Disambiguate duplicates
            idx = 2
            new_name = f"{name} #{idx}"
            while new_name in results:
                idx += 1
                new_name = f"{name} #{idx}"
            name = new_name
        results[name] = status

    def build_case_name(case: dict) -> str:
        full_name = case.get("fullName")
        if full_name:
            return full_name
        name = case.get("name")
        if name:
            return name
        title = case.get("title") or case.get("testName")
        ancestors = case.get("ancestorTitles") or case.get("suiteNames") or []
        if isinstance(ancestors, list) and ancestors:
            if title:
                return " ".join([*ancestors, title])
            return " ".join(ancestors)
        if title:
            return title
        return "unknown_test"

    def handle_suite(suite: dict) -> None:
        suite_name = suite.get("name") or suite.get("testFilePath") or suite.get("file") or "unknown_suite"
        assertions = suite.get("assertionResults") or suite.get("assertions") or suite.get("tests") or []
        if isinstance(assertions, list):
            for case in assertions:
                if not isinstance(case, dict):
                    continue
                case_name = build_case_name(case)
                status = normalize_status(case.get("status"))
                if status is None:
                    # Heuristic fallback
                    if case.get("failureMessages"):
                        status = "fail"
                    else:
                        status = "pass"
                add_result(f"{suite_name}::{case_name}", status)

    def process_json(obj) -> None:
        if isinstance(obj, dict):
            if "testResults" in obj and isinstance(obj["testResults"], list):
                for suite in obj["testResults"]:
                    if isinstance(suite, dict):
                        handle_suite(suite)
            if "assertionResults" in obj and isinstance(obj["assertionResults"], list):
                # Sometimes a suite object without name or a single report fragment
                if "name" in obj or "testFilePath" in obj or "file" in obj:
                    handle_suite(obj)
                else:
                    suite = {"name": obj.get("name", "unknown_suite"), "assertionResults": obj["assertionResults"]}
                    handle_suite(suite)
            for value in obj.values():
                process_json(value)
        elif isinstance(obj, list):
            for item in obj:
                process_json(item)

    # Extract JSON objects/arrays from concatenated logs.
    decoder = json.JSONDecoder()
    idx = 0
    while idx < len(log):
        match = re.search(r"[\{\[]", log[idx:])
        if not match:
            break
        start = idx + match.start()
        try:
            obj, end = decoder.raw_decode(log[start:])
        except json.JSONDecodeError:
            idx = start + 1
            continue
        idx = start + end
        process_json(obj)

    # Parse JUnit-like XML fragments.
    for m in re.finditer(r"<testcase\b[^>]*(?:/>|>.*?</testcase>)", log, re.S | re.I):
        block = m.group(0)
        # Extract attributes
        name_match = re.search(r'\bname=["\']([^"\']+)["\']', block)
        class_match = re.search(r'\bclassname=["\']([^"\']+)["\']', block)
        name = name_match.group(1) if name_match else "unknown_test"
        classname = class_match.group(1) if class_match else ""
        full_name = f"{classname}::{name}" if classname else name
        status = "pass"
        if re.search(r"<failure\b", block, re.I) or re.search(r"<error\b", block, re.I):
            status = "fail"
        elif re.search(r"<skipped\b", block, re.I):
            status = "skip"
        add_result(full_name, status)

    # Parse common plaintext patterns.
    pytest_re = re.compile(
        r"^(?P<name>\S+::\S+)\s+(?P<status>PASSED|FAILED|SKIPPED|XFAILED|XPASSED|ERROR)\b",
        re.M,
    )
    for m in pytest_re.finditer(log):
        status = normalize_status(m.group("status"))
        if status:
            add_result(m.group("name"), status)

    unittest_re = re.compile(r"^(?P<name>[\w\.]+)\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|SKIP)\b", re.M)
    for m in unittest_re.finditer(log):
        status = normalize_status(m.group("status"))
        if status:
            add_result(m.group("name"), status)

    go_re = re.compile(r"^---\s+(PASS|FAIL|SKIP):\s+(?P<name>.+?)(?:\s+\(|$)", re.M)
    for m in go_re.finditer(log):
        status = normalize_status(m.group(1))
        if status:
            add_result(m.group("name"), status)

    symbol_re = re.compile(r"^\s*[✓✔√]\s+(?P<name>.+)$", re.M)
    for m in symbol_re.finditer(log):
        add_result(m.group("name").strip(), "pass")

    symbol_fail_re = re.compile(r"^\s*[✕✖×]\s+(?P<name>.+)$", re.M)
    for m in symbol_fail_re.finditer(log):
        add_result(m.group("name").strip(), "fail")

    symbol_skip_re = re.compile(r"^\s*[○◌]\s+(?P<name>.+)$", re.M)
    for m in symbol_skip_re.finditer(log):
        add_result(m.group("name").strip(), "skip")

    return results

def parser(log: str) -> dict[str, str]:
    import json
    import re
    import xml.etree.ElementTree as ET
    results: dict[str, str] = {}

    def norm_status(status: str) -> str:
        status = (status or "").lower()
        if status in {"passed", "pass", "ok", "success"}:
            return "pass"
        if status in {"failed", "fail", "error"}:
            return "fail"
        if status in {"skipped", "skip", "pending", "todo", "disabled", "xfailed", "xfail"}:
            return "skip"
        return "fail"

    def add_result(name: str, status: str) -> None:
        if not name:
            return
        if name in results:
            return
        results[name] = status

    def parse_vitest_json(data: dict) -> None:
        test_results = data.get("testResults") or []
        for idx, suite in enumerate(test_results):
            suite_name = suite.get("name") or suite.get("testFilePath") or suite.get("file") or ""
            assertions = suite.get("assertionResults") or []
            if assertions:
                for test in assertions:
                    title = test.get("title") or ""
                    ancestor_titles = test.get("ancestorTitles") or []
                    full_name = test.get("fullName") or " / ".join([t for t in ancestor_titles + [title] if t]).strip()
                    if not full_name:
                        full_name = title or "(unnamed test)"
                    test_name = f"{suite_name}::{full_name}" if suite_name else full_name
                    add_result(test_name, norm_status(test.get("status")))
            else:
                suite_status = suite.get("status")
                if suite_status:
                    suite_id = suite_name or f"suite_{idx}"
                    add_result(f"{suite_id}::(suite)", norm_status(suite_status))

    def extract_json_objects(text: str) -> list[str]:
        objs = []
        depth = 0
        in_str = False
        escape = False
        start = None
        for i, ch in enumerate(text):
            if in_str:
                if escape:
                    escape = False
                elif ch == "\\":
                    escape = True
                elif ch == '"':
                    in_str = False
                continue
            else:
                if ch == '"':
                    in_str = True
                    continue
                if ch == "{":
                    if depth == 0:
                        start = i
                    depth += 1
                elif ch == "}":
                    if depth > 0:
                        depth -= 1
                        if depth == 0 and start is not None:
                            objs.append(text[start:i + 1])
                            start = None
        return objs

    # Parse JSON blobs (Vitest/Jest-style)
    for blob in extract_json_objects(log):
        try:
            data = json.loads(blob)
        except json.JSONDecodeError:
            continue
        if isinstance(data, dict) and "testResults" in data:
            parse_vitest_json(data)

    # JUnit XML parsing
    if "<testsuite" in log or "<testsuites" in log:
        xml_blocks = []
        xml_blocks += re.findall(r"<testsuites[\s\S]*?</testsuites>", log)
        xml_blocks += re.findall(r"<testsuite[\s\S]*?</testsuite>", log)
        for block in xml_blocks:
            try:
                root = ET.fromstring(block)
            except ET.ParseError:
                continue
            for tc in root.iter("testcase"):
                name = tc.attrib.get("name", "")
                classname = tc.attrib.get("classname", "")
                file = tc.attrib.get("file", "")
                full = f"{classname}.{name}".strip(".") if classname else name
                test_name = f"{file}::{full}" if file else full
                status = "pass"
                if tc.find("failure") is not None or tc.find("error") is not None:
                    status = "fail"
                elif tc.find("skipped") is not None:
                    status = "skip"
                add_result(test_name, status)

    # pytest style lines
    for m in re.finditer(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|XFAIL|XPASS|ERROR)\b", log, re.M):
        name, status = m.group(1), m.group(2)
        add_result(name, norm_status(status))

    # unittest style lines
    for m in re.finditer(r"^([A-Za-z0-9_./:-]+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", log, re.M):
        name, status = m.group(1), m.group(2)
        add_result(name, norm_status(status))

    # Go test lines
    for m in re.finditer(r"^---\s+(PASS|FAIL|SKIP):\s+([^\s]+)", log, re.M):
        status, name = m.group(1), m.group(2)
        add_result(name, norm_status(status))

    # Jest/Vitest symbol lines
    for m in re.finditer(r"^\s*[✓√]\s+(.*)$", log, re.M):
        add_result(m.group(1).strip(), "pass")
    for m in re.finditer(r"^\s*[✕×]\s+(.*)$", log, re.M):
        add_result(m.group(1).strip(), "fail")
    for m in re.finditer(r"^\s*[○◌]\s+(.*)$", log, re.M):
        add_result(m.group(1).strip(), "skip")

    return results

