def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}
    last_pkg: str | None = None

    status_map = {
        "PASS": "pass",
        "FAIL": "fail",
        "SKIP": "skip",
        "PASSED": "pass",
        "FAILED": "fail",
        "ERROR": "fail",
        "SKIPPED": "skip",
        "OK": "pass",
    }

    go_status_re = re.compile(r"---\s+(PASS|FAIL|SKIP):\s+([^\s]+)")
    pytest_re = re.compile(r"(?P<name>\S+::\S+)\s+(?P<status>PASSED|FAILED|SKIPPED|ERROR)")
    unittest_re = re.compile(r"^(?P<name>[\w\.]+)\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|skipped)", re.IGNORECASE)
    jest_re = re.compile(r"^[\s]*(?P<symbol>[✓✕○])\s+(?P<name>.+)$")
    # Generic TAP-like: "ok 1 test name", "not ok 1 test name"
    tap_re = re.compile(r"^(?P<status>ok|not ok)\s+\d+\s+(?P<name>.+)$", re.IGNORECASE)

    def set_result(name: str | None, status: str) -> None:
        if not name:
            return
        status = status.lower()
        prev = results.get(name)
        if status == "fail":
            results[name] = "fail"
        elif status == "pass":
            if prev != "fail":
                results[name] = "pass"
        elif status == "skip":
            if prev not in ("fail", "pass"):
                results[name] = "skip"

    def parse_output(text: str, pkg: str | None) -> None:
        for line in text.splitlines():
            line = line.strip()
            if not line:
                continue

            m = go_status_re.search(line)
            if m:
                status = status_map[m.group(1)]
                test = m.group(2)
                name = f"{pkg}/{test}" if pkg else test
                set_result(name, status)
                continue

            m = pytest_re.search(line)
            if m:
                status = status_map[m.group("status")]
                name = m.group("name")
                set_result(name, status)
                continue

            m = unittest_re.search(line)
            if m:
                status = status_map[m.group("status").upper()]
                name = m.group("name")
                set_result(name, status)
                continue

            m = tap_re.search(line)
            if m:
                status = "pass" if m.group("status").lower() == "ok" else "fail"
                name = m.group("name").strip()
                set_result(name, status)
                continue

            m = jest_re.search(line)
            if m:
                symbol = m.group("symbol")
                name = m.group("name").strip()
                if symbol == "✓":
                    set_result(name, "pass")
                elif symbol == "✕":
                    set_result(name, "fail")
                elif symbol == "○":
                    set_result(name, "skip")

    for raw_line in log.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        parsed = False
        if line.startswith("{") and line.endswith("}"):
            try:
                data = json.loads(line)
                parsed = True
            except Exception:
                parsed = False

        if parsed:
            pkg = data.get("Package") or last_pkg
            if data.get("Package"):
                last_pkg = data.get("Package")
            action = data.get("Action")
            test = data.get("Test")
            if test and action in ("pass", "fail", "skip"):
                name = f"{pkg}/{test}" if pkg else test
                set_result(name, action)
            output = data.get("Output")
            if output:
                parse_output(output, pkg)
            continue

        parse_output(line, last_pkg)

    return results

