def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}
    precedence = {"pass": 0, "skip": 1, "fail": 2}

    go_status_re = re.compile(r"---\s+(PASS|FAIL|SKIP):\s+([^\s]+)")
    pytest_re = re.compile(r"(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)")
    unittest_re = re.compile(r"^(\S+\.\S+)\s+\.\.\.\s+(ok|OK|FAIL|ERROR|skipped|SKIP)")
    jest_pass_re = re.compile(r"^[✓✔]\s+(.+)")
    jest_fail_re = re.compile(r"^[✕✖×]\s+(.+)")
    jest_skip_re = re.compile(r"^[○◌]\s+(.+)")
    # Require TAP-style "-" separator to avoid matching go package summaries like "ok  \tpkg"
    tap_re = re.compile(r"^(not )?ok(?:\s+\d+)?\s*-\s*([^\#]*?)(?:\s*#\s*(SKIP|skip))?$", re.IGNORECASE)

    def set_result(name: str, status: str) -> None:
        if not name:
            return
        prev = results.get(name)
        if prev is None or precedence[status] > precedence[prev]:
            results[name] = status

    def handle_output_line(line: str, pkg: str | None) -> None:
        line = line.strip()
        if not line:
            return

        m = go_status_re.search(line)
        if m:
            status = m.group(1).lower()
            test = m.group(2)
            name = f"{pkg}.{test}" if pkg else test
            set_result(name, status)
            return

        m = pytest_re.search(line)
        if m:
            status = m.group(2).lower()
            if status in ("failed", "error"):
                status = "fail"
            elif status in ("skipped", "xfailed", "xfail"):
                status = "skip"
            else:
                status = "pass"
            set_result(m.group(1), status)
            return

        m = unittest_re.search(line)
        if m:
            raw = m.group(2).lower()
            if raw in ("fail", "error"):
                status = "fail"
            elif raw.startswith("skip"):
                status = "skip"
            else:
                status = "pass"
            set_result(m.group(1), status)
            return

        m = jest_pass_re.search(line)
        if m:
            set_result(m.group(1).strip(), "pass")
            return
        m = jest_fail_re.search(line)
        if m:
            set_result(m.group(1).strip(), "fail")
            return
        m = jest_skip_re.search(line)
        if m:
            set_result(m.group(1).strip(), "skip")
            return

        m = tap_re.search(line)
        if m:
            is_not = m.group(1)
            name = m.group(2).strip() or "tap_test"
            if m.group(3):
                status = "skip"
            else:
                status = "fail" if is_not else "pass"
            set_result(name, status)
            return

    last_pkg: str | None = None

    for line in log.splitlines():
        raw = line.strip()
        if not raw:
            continue
        try:
            rec = json.loads(raw)
        except json.JSONDecodeError:
            handle_output_line(raw, last_pkg)
            continue

        pkg = rec.get("Package") or last_pkg
        if pkg:
            last_pkg = pkg

        action = rec.get("Action")
        test = rec.get("Test")
        if action in ("pass", "fail", "skip") and test:
            status = "fail" if action == "fail" else "skip" if action == "skip" else "pass"
            name = f"{pkg}.{test}" if pkg else test
            set_result(name, status)
            continue

        if action == "output":
            output = rec.get("Output", "")
            for out_line in output.splitlines():
                handle_output_line(out_line, pkg)

    return results

