            return
        current = results.get(name)
        if current is None or priority[status] > priority.get(current, 0):
            results[name] = status

    def normalize_status(raw: str, fallback_fail: bool = False) -> str:
        raw = (raw or "").lower()
        if raw in ("passed", "pass", "success"):
            return "pass"
        if raw in ("failed", "fail", "error"):
            return "fail"
        if raw in ("skipped", "skip", "pending", "todo", "disabled"):
            return "skip"
        return "fail" if fallback_fail else "fail"

    def parse_assertion(assertion: dict) -> None:
        name = assertion.get("fullName")
        if not name:
            title = assertion.get("title") or ""
            ancestors = assertion.get("ancestorTitles") or []
            if ancestors:
                name = " ".join([*ancestors, title]).strip()
            else:
                name = title
        status = normalize_status(assertion.get("status"), fallback_fail=True)
        set_result(name, status)

    def parse_suite(suite: dict) -> None:
        assertions = suite.get("assertionResults") or []
        for assertion in assertions:
            if isinstance(assertion, dict):
                parse_assertion(assertion)

    def parse_data(data) -> None:
        if isinstance(data, list):
            for item in data:
                parse_data(item)
            return
        if not isinstance(data, dict):
            return
        if "testResults" in data:
            for suite in data.get("testResults") or []:
                if isinstance(suite, dict):
                    parse_suite(suite)
        elif "assertionResults" in data:
            parse_suite(data)

    def extract_candidates(text: str) -> list[str]:
        candidates = []
        stack = 0
        start = None
        for i, ch in enumerate(text):
            if ch == "{":
                if stack == 0:
                    start = i
                stack += 1
            elif ch == "}" and stack:
                stack -= 1
                if stack == 0 and start is not None:
                    candidates.append(text[start : i + 1])
                    start = None
        return candidates

    data = None
    stripped = log.strip()
    if stripped:
        try:
            data = json.loads(stripped)
        except Exception:
            for candidate in extract_candidates(log):
                try:
                    parsed = json.loads(candidate)
                except Exception:
                    continue
                if isinstance(parsed, dict) and (
                    "testResults" in parsed or "assertionResults" in parsed or "numTotalTests" in parsed
                ):
                    data = parsed
            if data is None:
                # maybe a JSON array in the log
                for candidate in extract_candidates(log):
                    try:
                        parsed = json.loads(candidate)
                    except Exception:
                        continue
                    if isinstance(parsed, list):
                        data = parsed
                        break

    if data is not None:
        parse_data(data)

    # Fallback: parse common textual outputs if JSON missing
    if not results:
        # Jest symbols
        for line in log.splitlines():
            m = re.match(r"^\s*[✓]\s+(.+)$", line)
            if m:
                set_result(m.group(1).strip(), "pass")
                continue
            m = re.match(r"^\s*[✕x]\s+(.+)$", line)
            if m:
                set_result(m.group(1).strip(), "fail")
                continue
            m = re.match(r"^\s*[○-]\s+(.+)$", line)
            if m:
                set_result(m.group(1).strip(), "skip")
                continue

        # pytest format
        for line in log.splitlines():
            m = re.match(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)", line)
            if m:
                status = normalize_status(m.group(2))
                set_result(m.group(1), status)

        # Go test format
        for line in log.splitlines():
            m = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", line)
            if m:
                status = normalize_status(m.group(1))
                set_result(m.group(2), status)

        # unittest format
        for line in log.splitlines():
            m = re.match(r"^(\S+)\s+\.\.\.\s+(ok|FAIL|ERROR|SKIP(?:PED)?)", line, re.IGNORECASE)
            if m:
                status = normalize_status(m.group(2))
                set_result(m.group(1), status)

    return results

