log_parser:
def parser(log: str) -> dict[str, str]:
    import json
    import re
    from typing import Any

    results: dict[str, str] = {}

    def norm_status(status: str | None) -> str:
        if not status:
            return "fail"
        s = status.lower()
        if s in {"passed", "pass", "ok", "success"}:
            return "pass"
        if s in {"failed", "fail", "error", "errored"}:
            return "fail"
        if s in {"pending", "skipped", "skip", "disabled", "todo", "xfail", "xfailed"}:
            return "skip"
        if s in {"xpass", "unexpected pass"}:
            return "fail"
        return "fail"

    severity = {"pass": 0, "skip": 1, "fail": 2}

    def add_result(name: str | None, status: str) -> None:
        if not name:
            return
        name = name.strip()
        if not name:
            return
        status = norm_status(status)
        if name in results:
            # Keep the worst status
            if severity[status] > severity[results[name]]:
                results[name] = status
        else:
            results[name] = status

    def parse_jest_json(data: Any) -> None:
        if isinstance(data, list):
            for item in data:
                parse_jest_json(item)
            return
        if not isinstance(data, dict):
            return
        # Jest JSON often has "testResults"
        test_results = data.get("testResults") or data.get("results") or []
        if isinstance(test_results, dict):
            # Sometimes nested under results
            test_results = test_results.get("testResults", [])
        if not isinstance(test_results, list):
            return
        for suite in test_results:
            if not isinstance(suite, dict):
                continue
            assertions = suite.get("assertionResults")
            if assertions:
                for assertion in assertions:
                    if not isinstance(assertion, dict):
                        continue
                    name = assertion.get("fullName")
                    if not name:
                        parts = []
                        ancestors = assertion.get("ancestorTitles") or []
                        if isinstance(ancestors, list):
                            parts.extend([str(a) for a in ancestors if a])
                        title = assertion.get("title")
                        if title:
                            parts.append(str(title))
                        name = " ".join(parts) if parts else assertion.get("title")
                    status = assertion.get("status")
                    add_result(name, status)
            else:
                # If no assertions, at least record suite status
                suite_name = suite.get("name") or suite.get("testFilePath")
                suite_status = suite.get("status")
                if suite_name and suite_status:
                    add_result(str(suite_name), suite_status)

    # 1) Try direct JSON parse
    stripped = log.strip()
    if stripped:
        try:
            data = json.loads(stripped)
            parse_jest_json(data)
        except Exception:
            pass

    # 2) Extract JSON objects from noisy logs
    if not results:
        objs = []
        depth = 0
        start = None
        for i, ch in enumerate(log):
            if ch == "{":
                if depth == 0:
                    start = i
                depth += 1
            elif ch == "}":
                if depth > 0:
                    depth -= 1
                    if depth == 0 and start is not None:
                        fragment = log[start:i + 1]
                        try:
                            data = json.loads(fragment)
                            objs.append(data)
                        except Exception:
                            pass
                        start = None
        for data in objs:
            parse_jest_json(data)

    # 3) XML (JUnit-like) parsing
    if not results and ("<testsuite" in log or "<testsuites" in log):
        import xml.etree.ElementTree as ET
        xml_text = log
        # try to extract a reasonable xml fragment
        if "<testsuites" in log:
            start = log.find("<testsuites")
            end = log.rfind("</testsuites>")
            if start != -1 and end != -1:
                xml_text = log[start:end + len("</testsuites>")]
        elif "<testsuite" in log:
            start = log.find("<testsuite")
            end = log.rfind("</testsuite>")
            if start != -1 and end != -1:
                xml_text = log[start:end + len("</testsuite>")]
        try:
            root = ET.fromstring(xml_text)
            for testcase in root.iter("testcase"):
                name = testcase.get("name")
                classname = testcase.get("classname")
                full = f"{classname} {name}".strip() if classname else name
                status = "pass"
                for child in testcase:
                    if child.tag in {"failure", "error"}:
                        status = "fail"
                        break
                    if child.tag == "skipped":
                        status = "skip"
                add_result(full, status)
        except Exception:
            pass

    # 4) Text-based fallbacks
    # pytest style: file::test_name STATUS
    for line in log.splitlines():
        m = re.match(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\b", line)
        if m:
            add_result(m.group(1), m.group(2))
            continue
        # unittest style: TestName ... ok/FAIL/ERROR
        m = re.match(r"^(\S+)\s+\.\.\.\s+(ok|OK|FAIL|ERROR|skipped|SKIPPED)\b", line)
        if m:
            add_result(m.group(1), m.group(2))
            continue
        # go test style
        m = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(.+?)(?:\s+\(|$)", line)
        if m:
            add_result(m.group(2), m.group(1))
            continue
        # Jest text output symbols
        m = re.match(r"^\s*([✓✔])\s+(.+)$", line)
        if m:
            add_result(m.group(2), "pass")
            continue
        m = re.match(r"^\s*([✕✖×])\s+(.+)$", line)
        if m:
            add_result(m.group(2), "fail")
            continue
        m = re.match(r"^\s*([○◌])\s+(.+)$", line)
        if m:
            add_result(m.group(2), "skip")
            continue

    return results

