+package io.github.hectorvent.floci.core.common;
+
+import jakarta.ws.rs.container.ContainerRequestContext;
+import jakarta.ws.rs.container.ContainerRequestFilter;
+import jakarta.ws.rs.container.PreMatching;
+import jakarta.ws.rs.core.MediaType;
+import jakarta.ws.rs.ext.Provider;
+
+import java.net.URI;
+import java.util.regex.Pattern;
+
+/**
+ * Pre-matching filter that rewrites SQS JSON 1.0 requests sent to the queue URL path
+ * (/{accountId}/{queueName}) to POST / so they are handled by AwsJsonController.
+ * <p>
+ * Newer AWS SDKs (e.g. aws-sdk-sqs Ruby gem >= 1.71) route operations to the queue URL
+ * rather than POST /. Without this filter, those requests match S3Controller's
+ * /{bucket}/{key:.+} handler and return NoSuchBucket errors.
+ */
+@Provider
+@PreMatching
+public class SqsQueueUrlRouterFilter implements ContainerRequestFilter {
+
+    private static final Pattern QUEUE_PATH = Pattern.compile("^/([^/]+)/([^/]+)$");
+
+    @Override
+    public void filter(ContainerRequestContext ctx) {
+
+        if (!"POST".equals(ctx.getMethod())) {
+            return;
+        }
+
+        String path = ctx.getUriInfo().getPath();
+        if (!QUEUE_PATH.matcher(path).matches()) {
+            return;
+        }
+
+        MediaType mt = ctx.getMediaType();
+        if (mt == null) {
+            return;
+        }
+
+        boolean isSqsJson = "application".equals(mt.getType())
+                && "x-amz-json-1.0".equals(mt.getSubtype())
+                && isSqsTarget(ctx.getHeaderString("X-Amz-Target"));
+
+        // S3 never receives form-encoded POSTs to /{bucket}/{key} paths —
+        // S3 presigned POST always goes to /{bucket}, not /{bucket}/{key}.
+        boolean isSqsQuery = "application".equals(mt.getType())
+                && "x-www-form-urlencoded".equals(mt.getSubtype());
+
+        if (!isSqsJson && !isSqsQuery) {
+            return;
+        }
+
+        URI rewritten = ctx.getUriInfo().getRequestUriBuilder()
+                .replacePath("/")
+                .build();
+        ctx.setRequestUri(rewritten);
+    }
+
+    private boolean isSqsTarget(String target) {
+        return target != null && target.startsWith("AmazonSQS.");
+    }
+}

log_parser:
def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results = {}
    if not log:
        return results

    text = re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f]', '', log)
    cleaned = re.sub(r'<\?xml[^>]*\?>', '', text)
    cleaned = re.sub(r'<!DOCTYPE[^>]*>', '', cleaned)

    def record(name, classname, status):
        key = f"{classname}::{name}" if classname else name
        results[key] = status

    def parse_attrs(attr_text):
        attrs = {}
        for m in re.finditer(r'(\w+)\s*=\s*"([^"]*)"', attr_text):
            attrs[m.group(1)] = m.group(2)
        for m in re.finditer(r"(\w+)\s*=\s*'([^']*)'", attr_text):
            attrs[m.group(1)] = m.group(2)
        return attrs

    wrapped = "<root>" + cleaned + "</root>"
    try:
        root = ET.fromstring(wrapped)
        for tc in root.iter():
            if not tc.tag.endswith("testcase"):
                continue
            attrib = tc.attrib
            name = attrib.get("name") or attrib.get("id")
            if not name:
                continue
            classname = attrib.get("classname") or attrib.get("className") or attrib.get("class")
            status_attr = (attrib.get("status") or attrib.get("result") or "").lower()
            status = "pass"
            if status_attr in {"skipped", "skip", "ignored", "disabled"}:
                status = "skip"
            elif status_attr in {"failure", "failed", "error", "errors"}:
                status = "fail"
            for child in tc:
                tag = child.tag
                if tag.endswith("failure") or tag.endswith("error"):
                    status = "fail"
                    break
            if status != "fail":
                for child in tc:
                    if child.tag.endswith("skipped"):
                        status = "skip"
                        break
            record(name, classname, status)
        if results:
            return results
    except ET.ParseError:
        pass

    testcase_pattern = re.compile(
        r"<testcase\b(?P<attrs>[^>]*?)(?:/>|>(?P<body>.*?)</testcase\s*>)",
        re.DOTALL | re.IGNORECASE,
    )
    for match in testcase_pattern.finditer(cleaned):
        attrs_text = match.group("attrs") or ""
        body = match.group("body") or ""
        attrs = parse_attrs(attrs_text)
        name = attrs.get("name") or attrs.get("id")
        if not name:
            continue
        classname = attrs.get("classname") or attrs.get("className") or attrs.get("class")
        status_attr = (attrs.get("status") or attrs.get("result") or "").lower()
        status = "pass"
        if status_attr in {"skipped", "skip", "ignored", "disabled"}:
            status = "skip"
        elif status_attr in {"failure", "failed", "error", "errors"}:
            status = "fail"
        if status == "pass":
            if re.search(r"<\s*(failure|error)\b", body, re.IGNORECASE):
                status = "fail"
            elif re.search(r"<\s*skipped\b", body, re.IGNORECASE):
                status = "skip"
        record(name, classname, status)

    if results:
        return results

    for line in log.splitlines():
        if "<" in line:
            continue
        line = line.strip()
        if not line:
            continue

        m = re.match(r'(.+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b', line)
        if m:
            name, status = m.group(1), m.group(2)
            results[name] = "fail" if status in {"FAILED", "ERROR"} else "skip" if status == "SKIPPED" else "pass"
            continue

        m = re.match(r'---\s+(PASS|FAIL|SKIP):\s+(\S+)', line)
        if m:
            status, name = m.group(1), m.group(2)
            results[name] = "pass" if status == "PASS" else "skip" if status == "SKIP" else "fail"
            continue

        m = re.match(r'([A-Za-z0-9_.-]+)\s+\.\.\.\s+(ok|OK|FAIL|ERROR|skipped|SKIPPED)', line)
        if m:
            name, status = m.group(1), m.group(2).lower()
            results[name] = "pass" if status == "ok" else "skip" if status == "skipped" else "fail"
            continue

        m = re.match(r'(✓|✔)\s+(.*)', line)
        if m:
            results[m.group(2).strip()] = "pass"
            continue
        m = re.match(r'(✕|✖|✗|×)\s+(.*)', line)
        if m:
            results[m.group(2).strip()] = "fail"
            continue
        m = re.match(r'(○|◌)\s+(.*)', line)
        if m:
            results[m.group(2).strip()] = "skip"
            continue

    return results

