def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}
    running: dict[str, set[str]] = {}
    current_pkg: str | None = None

    ansi_re = re.compile(r"\x1b\[[0-9;]*m")
    pass_fail_re = re.compile(r"--- (PASS|FAIL|SKIP):\s+([^\s]+)")
    run_re = re.compile(r"=== (RUN|PAUSE|CONT)\s+([^\s]+)")
    pkg_line_re = re.compile(r"^(ok|FAIL|\?)\s+\t?([^\s]+)")
    fail_pkg_re = re.compile(r"^FAIL\s+\t?([^\s]+)")

    def set_status(pkg: str | None, test: str, status: str) -> None:
        name = f"{pkg}/{test}" if pkg else test
        existing = results.get(name)
        if existing == "fail":
            return
        if status == "fail":
            results[name] = "fail"
        else:
            results[name] = status

    def mark_running(pkg: str | None, test: str) -> None:
        if not pkg:
            return
        running.setdefault(pkg, set()).add(test)

    def finalize_pkg_fail(pkg: str) -> None:
        for test in list(running.get(pkg, set())):
            name = f"{pkg}/{test}"
            if name not in results:
                results[name] = "fail"

    def process_output(output: str, pkg: str | None) -> None:
        if not output:
            return
        clean = ansi_re.sub("", output)
        for line in clean.splitlines():
            line = line.strip()
            if not line:
                continue
            m = run_re.search(line)
            if m:
                _, test = m.groups()
                mark_running(pkg, test)
            m = pass_fail_re.search(line)
            if m:
                status_raw, test = m.groups()
                status = status_raw.lower()
                set_status(pkg, test, status)

    for raw_line in log.splitlines():
        line = raw_line.strip("\n")
        if not line.strip():
            continue

        obj = None
        if line.lstrip().startswith("{"):
            try:
                obj = json.loads(line)
            except Exception:
                obj = None

        if obj is not None:
            pkg = obj.get("Package") or current_pkg
            if obj.get("Package"):
                current_pkg = obj.get("Package")
            action = obj.get("Action")
            test = obj.get("Test")

            if action == "run" and test:
                mark_running(pkg, test)
            elif action in ("pass", "fail", "skip") and test:
                set_status(pkg, test, action)
            elif action == "fail" and not test and pkg:
                finalize_pkg_fail(pkg)
            elif action == "output":
                process_output(obj.get("Output", ""), pkg)
            continue

        # non-JSON fallback
        m_pkg = pkg_line_re.search(line)
        if m_pkg:
            current_pkg = m_pkg.group(2)
            if m_pkg.group(1) == "FAIL":
                finalize_pkg_fail(current_pkg)
        m_fail_pkg = fail_pkg_re.search(line)
        if m_fail_pkg:
            finalize_pkg_fail(m_fail_pkg.group(1))

        process_output(line, current_pkg)

    return results

def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}
    last_package = None

    def update(name: str, status: str) -> None:
        if not name or status not in ("pass", "fail", "skip"):
            return
        prev = results.get(name)
        if prev == "fail":
            return
        if status == "fail":
            results[name] = "fail"
            return
        if status == "skip":
            if prev != "fail":
                results[name] = "skip"
            return
        if status == "pass":
            if prev not in ("fail", "skip"):
                results[name] = "pass"

    def normalize_status(raw: str) -> str | None:
        raw = raw.lower()
        if raw.startswith("pass"):
            return "pass"
        if raw.startswith("fail") or raw.startswith("error"):
            return "fail"
        if raw.startswith("skip"):
            return "skip"
        return None

    def parse_output_line(line: str, package: str | None) -> None:
        line = line.rstrip("\n")
        if not line:
            return
        # Go test status line: --- PASS: TestName (0.00s)
        if line.startswith("--- "):
            try:
                prefix, rest = line[4:].split(":", 1)
            except ValueError:
                return
            status = normalize_status(prefix.strip())
            if not status:
                return
            name = rest.strip()
            if " (" in name:
                name = name.rsplit(" (", 1)[0]
            if package:
                update(f"{package}/{name}", status)
            else:
                update(name, status)
            return
        # pytest-like
        m = re.search(r"^\s*(.+?)::(\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\s*$", line)
        if m:
            name = f"{m.group(1)}::{m.group(2)}"
            status = normalize_status(m.group(3))
            if status:
                update(name, status)
            return
        # unittest-like
        m = re.search(r"^\s*([\w\.]+)\s+\.\.\.\s+(ok|FAIL|ERROR|SKIP)\s*$", line)
        if m:
            name = m.group(1)
            status = normalize_status(m.group(2))
            if status:
                update(name, status)
            return
        # Jest-like
        m = re.search(r"^\s*[✓✕○]\s+(.+)$", line)
        if m:
            symbol = line.strip()[0]
            status = "pass" if symbol == "✓" else "fail" if symbol == "✕" else "skip"
            update(m.group(1).strip(), status)
            return

    for raw_line in log.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith("{"):
            try:
                entry = json.loads(line)
            except json.JSONDecodeError:
                parse_output_line(raw_line, last_package)
                continue
            package = entry.get("Package") or last_package
            if package:
                last_package = package
            action = entry.get("Action")
            test = entry.get("Test")
            if action in ("pass", "fail", "skip") and test and package:
                status = normalize_status(action)
                if status:
                    update(f"{package}/{test}", status)
                continue
            if action == "output":
                output = entry.get("Output", "")
                if output:
                    for out_line in output.splitlines():
                        parse_output_line(out_line, package)
            continue
        # Non-JSON lines
        parse_output_line(raw_line, last_package)

    return results

def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    priority = {"pass": 1, "skip": 2, "fail": 3}

    def update(name: str, status: str) -> None:
        if not name or status not in priority:
            return
        prev = results.get(name)
        if prev is None or priority[status] >= priority[prev]:
            results[name] = status

    def parse_go_status(text: str, pkg: str | None) -> None:
        if not text:
            return
        # Match go test status lines, capture name until " (" or end
        for m in re.finditer(r"--- (PASS|FAIL|SKIP): (.+?)(?: \(|$)", text):
            status = m.group(1).lower()
            testname = m.group(2).strip()
            name = f"{pkg}.{testname}" if pkg else testname
            update(name, status)

    def parse_pytest(line: str) -> None:
        m = re.search(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", line)
        if m:
            status = m.group(2).lower()
            if status == "error":
                status = "fail"
            update(m.group(1), status)

    def parse_unittest(line: str) -> None:
        m = re.search(r"^([\w\.]+)\s+\(.*\)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", line)
        if m:
            status = m.group(2).lower()
            if status == "ok":
                status = "pass"
            elif status in ("fail", "error"):
                status = "fail"
            elif status == "skipped":
                status = "skip"
            update(m.group(1), status)

    def parse_jest(line: str) -> None:
        m = re.search(r"^\s*(✓|✔)\s+(.+)$", line)
        if m:
            update(m.group(2).strip(), "pass")
            return
        m = re.search(r"^\s*(✕|✖|×)\s+(.+)$", line)
        if m:
            update(m.group(2).strip(), "fail")
            return
        m = re.search(r"^\s*(○)\s+(.+)$", line)
        if m:
            update(m.group(2).strip(), "skip")
            return

    # Try to parse entire log as JUnit XML if it looks like XML
    if "<testsuite" in log and "<testcase" in log:
        try:
            import xml.etree.ElementTree as ET

            root = ET.fromstring(log.strip())
            for tc in root.iter("testcase"):
                name = tc.attrib.get("name")
                classname = tc.attrib.get("classname")
                full = f"{classname}.{name}" if classname and name else name
                status = "pass"
                if tc.find("failure") is not None or tc.find("error") is not None:
                    status = "fail"
                elif tc.find("skipped") is not None:
                    status = "skip"
                if full:
                    update(full, status)
        except Exception:
            pass

    current_pkg: str | None = None

    for raw_line in log.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        rec = None
        try:
            rec = json.loads(line)
        except json.JSONDecodeError:
            rec = None

        if rec is not None and isinstance(rec, dict):
            pkg = rec.get("Package") or current_pkg
            if rec.get("Package"):
                current_pkg = rec.get("Package")
            action = rec.get("Action")
            test = rec.get("Test")

            if action in ("pass", "fail", "skip") and test:
                name = f"{pkg}.{test}" if pkg else test
                status = "fail" if action == "fail" else "skip" if action == "skip" else "pass"
                update(name, status)
                continue

            out = rec.get("Output")
            if out:
                for out_line in out.splitlines():
                    parse_go_status(out_line, pkg)
                    parse_pytest(out_line)
                    parse_unittest(out_line)
                    parse_jest(out_line)
            continue

        # Non-JSON line parsing
        parse_go_status(line, current_pkg)
        parse_pytest(line)
        parse_unittest(line)
        parse_jest(line)

    return results

