def parser(log: str) -> dict[str, str]:
    import json
    import re
    from xml.etree import ElementTree as ET

    results: dict[str, str] = {}

    def normalize_status(status: str | None) -> str | None:
        if status is None:
            return None
        status = str(status).strip().lower()
        if status in {"passed", "pass", "ok", "success"}:
            return "pass"
        if status in {"failed", "fail", "error", "errors", "failure", "xpass"}:
            return "fail"
        if status in {"skipped", "skip", "pending", "todo", "disabled", "ignored", "xfailed", "xfail"}:
            return "skip"
        return None

    priority = {"pass": 1, "skip": 2, "fail": 3}

    def add_result(name: str | None, status: str | None) -> None:
        if not name:
            return
        norm = normalize_status(status)
        if norm is None:
            return
        existing = results.get(name)
        if existing is None or priority[norm] > priority[existing]:
            results[name] = norm

    def build_name(base: str | None, suite: str | None) -> str | None:
        if not base:
            return suite
        if not suite:
            return base
        if base.startswith(suite):
            return base
        return f"{suite} {base}"

    def parse_assertions(assertions, suite_name: str | None = None):
        if not isinstance(assertions, list):
            return
        for assertion in assertions:
            if not isinstance(assertion, dict):
                continue
            name = assertion.get("fullName")
            if not name:
                ancestor_titles = assertion.get("ancestorTitles") or assertion.get("ancestors") or []
                title = assertion.get("title") or assertion.get("name") or ""
                if isinstance(ancestor_titles, list):
                    name = " ".join([*ancestor_titles, title]).strip()
                else:
                    name = str(title).strip() if title else None
            name = build_name(name, suite_name)
            add_result(name, assertion.get("status") or assertion.get("state"))

    def parse_suite(suite: dict):
        suite_name = suite.get("name") or suite.get("testFilePath") or suite.get("file") or suite.get("path")
        parse_assertions(suite.get("assertionResults"), suite_name)
        # Handle suite-level failures without assertions
        if suite.get("status") in {"failed", "error"} and not suite.get("assertionResults"):
            add_result(suite_name, "fail")

    def parse_vitest_tasks(tasks, suite_path: str | None = None):
        if not isinstance(tasks, list):
            return
        for task in tasks:
            if not isinstance(task, dict):
                continue
            task_type = task.get("type")
            name = task.get("fullName") or task.get("name") or task.get("title")
            full_name = build_name(name, suite_path)
            status = task.get("status") or task.get("state")
            result_obj = task.get("result")
            if isinstance(result_obj, dict):
                status = status or result_obj.get("state") or result_obj.get("status")
            if task_type == "test" or (status and name):
                add_result(full_name, status)
            # recurse into nested suites/tasks
            parse_vitest_tasks(task.get("tasks"), full_name)
            parse_vitest_tasks(task.get("suites"), full_name)
            parse_vitest_tasks(task.get("children"), full_name)

    def walk_json(obj, suite_path: str | None = None):
        if isinstance(obj, dict):
            if "assertionResults" in obj:
                parse_suite(obj)
            if "testResults" in obj and isinstance(obj["testResults"], list):
                for suite in obj["testResults"]:
                    if isinstance(suite, dict):
                        parse_suite(suite)
            # Vitest-style structures
            if "tasks" in obj or "suites" in obj or "tests" in obj:
                parse_vitest_tasks(obj.get("tasks"), suite_path)
                parse_vitest_tasks(obj.get("suites"), suite_path)
                parse_vitest_tasks(obj.get("tests"), suite_path)
            # recurse into dict values
            for value in obj.values():
                walk_json(value, suite_path)
        elif isinstance(obj, list):
            for item in obj:
                walk_json(item, suite_path)

    # Parse JSON objects embedded in the log
    decoder = json.JSONDecoder()
    idx = 0
    length = len(log)
    while idx < length:
        while idx < length and log[idx].isspace():
            idx += 1
        if idx >= length:
            break
        try:
            obj, end = decoder.raw_decode(log, idx)
        except json.JSONDecodeError:
            idx += 1
            continue
        walk_json(obj)
        idx = end

    # Parse JUnit XML (testsuite/testcase)
    for match in re.finditer(r"<testsuite[\s\S]*?</testsuite>", log):
        xml_blob = match.group(0)
        try:
            root = ET.fromstring(xml_blob)
        except ET.ParseError:
            continue
        for testcase in root.iter("testcase"):
            name = testcase.get("name") or ""
            classname = testcase.get("classname") or ""
            full_name = f"{classname}.{name}".strip(".") if classname or name else None
            status = "pass"
            if testcase.find("failure") is not None or testcase.find("error") is not None:
                status = "fail"
            elif testcase.find("skipped") is not None:
                status = "skip"
            add_result(full_name, status)

    # Parse common text patterns
    # Go test
    for m in re.finditer(r"^---\s+(PASS|FAIL|SKIP):\s+([^(\n]+)", log, re.MULTILINE):
        add_result(m.group(2).strip(), m.group(1).lower())

    # pytest
    for m in re.finditer(r"^([^\s:]+::[^\s]+)\s+(PASSED|FAILED|SKIPPED|XFAIL|XPASS|ERROR)", log, re.MULTILINE):
        add_result(m.group(1).strip(), m.group(2).lower())

    # unittest
    for m in re.finditer(r"^([A-Za-z0-9_.]+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)", log, re.MULTILINE):
        add_result(m.group(1).strip(), m.group(2).lower())

    # Jest/Vitest symbol output
    for m in re.finditer(r"^\s*[✓✔]\s+(.+)$", log, re.MULTILINE):
        add_result(m.group(1).strip(), "pass")
    for m in re.finditer(r"^\s*[✕✖]\s+(.+)$", log, re.MULTILINE):
        add_result(m.group(1).strip(), "fail")
    for m in re.finditer(r"^\s*[○◌]\s+(.+)$", log, re.MULTILINE):
        add_result(m.group(1).strip(), "skip")

    return results

