def parser(log: str) -> dict[str, str]:
    import re
    import html
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def unique_name(name: str) -> str:
        if name not in results:
            return name
        idx = 2
        while f"{name} [{idx}]" in results:
            idx += 1
        return f"{name} [{idx}]"

    def add_result(name: str, status: str) -> None:
        if not name:
            return
        key = unique_name(name)
        results[key] = status

    def parse_status_from_attrs(attrs: dict[str, str]) -> str | None:
        status_attr = (attrs.get("status") or attrs.get("result") or "").lower()
        if status_attr in {"skipped", "skip", "ignored"}:
            return "skip"
        if status_attr in {"fail", "failed", "failure", "error"}:
            return "fail"
        if status_attr in {"pass", "passed", "success"}:
            return "pass"
        return None

    def make_test_name(classname: str, name: str) -> str:
        classname = html.unescape(classname or "").strip()
        name = html.unescape(name or "").strip()
        return f"{classname}::{name}" if classname else name

    # ---- XML extraction ----
    def extract_xml_block(text: str) -> str | None:
        # Prefer full <testsuites>...</testsuites>
        start = text.find("<testsuites")
        end_tag = "</testsuites>"
        if start != -1:
            end = text.rfind(end_tag)
            if end != -1:
                return text[start:end + len(end_tag)]
        # Fallback to single <testsuite> root
        start = text.find("<testsuite")
        end_tag = "</testsuite>"
        if start != -1:
            end = text.rfind(end_tag)
            if end != -1:
                return text[start:end + len(end_tag)]
        # Try from XML declaration
        start = text.find("<?xml")
        if start != -1:
            return text[start:]
        return None

    def clean_xml_text(text: str) -> str:
        # Remove invalid XML control chars
        return re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", text)

    xml_block = extract_xml_block(log)
    if xml_block:
        xml_block = clean_xml_text(xml_block)
        try:
            root = ET.fromstring(xml_block)
            for testcase in root.iter("testcase"):
                name = testcase.get("name") or ""
                classname = testcase.get("classname") or testcase.get("file") or ""
                test_name = make_test_name(classname, name)

                status = parse_status_from_attrs(testcase.attrib) or "pass"
                if testcase.find("skipped") is not None:
                    status = "skip"
                if testcase.find("failure") is not None or testcase.find("error") is not None:
                    status = "fail"

                add_result(test_name, status)
            if results:
                return results
        except ET.ParseError:
            pass

        # Fallback: regex parse testcase blocks
        testcase_pattern = re.compile(r"<testcase\b([^>/]*)(/?)>(.*?)</testcase>", re.DOTALL | re.IGNORECASE)
        self_close_pattern = re.compile(r"<testcase\b([^>/]*)\s*/>", re.IGNORECASE)
        for attrs_text, _, inner in testcase_pattern.findall(xml_block):
            attrs = dict(re.findall(r'(\w+)="(.*?)"', attrs_text))
            name = attrs.get("name", "")
            classname = attrs.get("classname") or attrs.get("file") or ""
            test_name = make_test_name(classname, name)
            status = parse_status_from_attrs(attrs) or "pass"
            inner_lower = inner.lower()
            if "<skipped" in inner_lower:
                status = "skip"
            if "<failure" in inner_lower or "<error" in inner_lower:
                status = "fail"
            add_result(test_name, status)

        for attrs_text in self_close_pattern.findall(xml_block):
            attrs = dict(re.findall(r'(\w+)="(.*?)"', attrs_text))
            name = attrs.get("name", "")
            classname = attrs.get("classname") or attrs.get("file") or ""
            test_name = make_test_name(classname, name)
            status = parse_status_from_attrs(attrs) or "pass"
            add_result(test_name, status)

        if results:
            return results

    # ---- Fallback: parse other formats ----
    patterns = [
        # pytest
        (re.compile(r"^(?P<name>.+?)\s+(?P<status>PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\s*$"),
         {"PASSED": "pass", "FAILED": "fail", "ERROR": "fail", "SKIPPED": "skip", "XFAIL": "skip", "XPASS": "fail"}),
        # go test
        (re.compile(r"^---\s+(?P<status>PASS|FAIL|SKIP):\s+(?P<name>\S+)\s*$"),
         {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}),
        # unittest
        (re.compile(r"^(?P<name>[\w./:-]+(?:\.[\w./:-]+)?)\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|skipped)\s*$", re.IGNORECASE),
         {"ok": "pass", "fail": "fail", "error": "fail", "skipped": "skip"}),
        # jest/ava-like symbols
        (re.compile(r"^\s*(?P<sym>[✓✕×✖○])\s+(?P<name>.+?)\s*$"),
         {"✓": "pass", "✕": "fail", "×": "fail", "✖": "fail", "○": "skip"}),
    ]

    for line in log.splitlines():
        line = line.strip()
        if not line:
            continue
        for pattern, mapping in patterns:
            match = pattern.match(line)
            if match:
                name = match.group("name").strip()
                raw_status = match.group("status") if "status" in match.groupdict() else match.group("sym")
                status = mapping.get(raw_status, "pass")
                add_result(name, status)
                break

    return results

