def parser(log: str) -> dict[str, str]:
    import json
    import os
    import re

    results: dict[str, str] = {}
    status_rank = {"pass": 0, "skip": 1, "fail": 2}

    def normalize_name(name: str) -> str:
        name = name.strip()
        name = re.sub(r'\s+#\s*SKIP$', '', name, flags=re.IGNORECASE).strip()
        return name

    def add_result(name: str, status: str) -> None:
        if not name:
            return
        name = normalize_name(name)
        if not name:
            return
        existing = results.get(name)
        if existing is None or status_rank[status] > status_rank[existing]:
            results[name] = status

    suite_stack: list[tuple[int, str]] = []

    def current_prefix() -> str:
        return " > ".join([n for _, n in suite_stack if n])

    def with_prefix(name: str) -> str:
        prefix = current_prefix()
        return f"{prefix} > {name}" if prefix else name

    def adjust_stack(indent: int) -> None:
        while suite_stack and indent < suite_stack[-1][0]:
            suite_stack.pop()

    def strip_time(name: str) -> str:
        # Strip trailing timing parentheses before optional # SKIP
        name = re.sub(r'\s+\([0-9][^)]+\)\s*(#\s*SKIP)?\s*$', '', name).strip()
        return name

    lines = log.splitlines()

    for line in lines:
        raw = line.rstrip("\n")
        if not raw.strip():
            continue

        indent = len(re.match(r'^(\s*)', raw).group(1).expandtabs(2))

        # Suite start lines: ▶ suite
        m = re.match(r'^(\s*)[▶>]\s+(.*)$', raw)
        if m:
            suite_indent = len(m.group(1).expandtabs(2))
            suite_name = strip_time(m.group(2).strip())
            while suite_stack and suite_indent <= suite_stack[-1][0]:
                suite_stack.pop()
            suite_stack.append((suite_indent, suite_name))
            continue

        adjust_stack(indent)

        # TAP output
        m = re.match(r'^\s*not ok\b(?:\s+\d+)?\s*(.*)$', raw, re.IGNORECASE)
        if m:
            add_result(with_prefix(m.group(1).strip() or raw.strip()), "fail")
            continue
        m = re.match(r'^\s*ok\b(?:\s+\d+)?\s*(.*)$', raw, re.IGNORECASE)
        if m:
            add_result(with_prefix(m.group(1).strip() or raw.strip()), "pass")
            continue

        # pytest output
        m = re.match(r'^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|XFAIL|XPASS|ERROR)\b', raw)
        if m:
            status_word = m.group(2)
            if status_word in ("PASSED", "XPASS"):
                status = "pass"
            elif status_word in ("SKIPPED", "XFAIL"):
                status = "skip"
            else:
                status = "fail"
            add_result(with_prefix(m.group(1)), status)
            continue

        # Go test output
        m = re.match(r'^---\s+(PASS|FAIL|SKIP):\s+(\S+)', raw)
        if m:
            status = "pass" if m.group(1) == "PASS" else "skip" if m.group(1) == "SKIP" else "fail"
            add_result(with_prefix(m.group(2)), status)
            continue

        # unittest output
        m = re.match(r'^(\S+)\s*(?:\([^)]+\))?\s*\.\.\.\s*(ok|FAIL|ERROR|skipped)', raw, re.IGNORECASE)
        if m:
            status_word = m.group(2).lower()
            status = "pass" if status_word == "ok" else "skip" if status_word == "skipped" else "fail"
            add_result(with_prefix(m.group(1)), status)
            continue

        # Jest failure bullet
        m = re.match(r'^\s*●\s+(.*)$', raw)
        if m:
            add_result(with_prefix(m.group(1).strip()), "fail")
            continue

        # Generic symbol-based lines
        m = re.match(r'^\s*([✔✓✖✗✕○﹣−–])\s+(.*)$', raw)
        if m:
            sym = m.group(1)
            name = m.group(2).strip()
            name = strip_time(name)
            # If this is a suite summary, pop and skip
            if suite_stack and indent == suite_stack[-1][0] and name == suite_stack[-1][1]:
                suite_stack.pop()
                continue
            if "# SKIP" in raw.upper():
                status = "skip"
            else:
                status = "pass" if sym in ("✔", "✓") else "skip" if sym in ("○", "﹣", "−", "–") else "fail"
            add_result(with_prefix(name), status)
            continue

        # Word-based status lines
        m = re.match(r'^\s*(PASS(?:ED)?|FAIL(?:ED)?|SKIP(?:PED)?|PENDING|TODO)\s+(.*)$', raw, re.IGNORECASE)
        if m:
            word = m.group(1).upper()
            name = strip_time(m.group(2).strip())
            if word.startswith("PASS"):
                status = "pass"
            elif word.startswith("SKIP") or word in ("PENDING", "TODO"):
                status = "skip"
            else:
                status = "fail"
            add_result(with_prefix(name), status)
            continue

        # Fallback: lines ending with timing parentheses but no marker
        m = re.match(r'^\s*(.+?)\s+\([0-9][^)]+\)\s*(#\s*SKIP)?\s*$', raw)
        if m:
            name = m.group(1).strip()
            status = "skip" if m.group(2) else "pass"
            if not re.match(r'^(Completed|Growth|Final|Average)\b', name):
                add_result(with_prefix(name), status)
            continue

    # Parse jest JSON from file if present
    for path in ("/testbed/jest-results.json", "jest-results.json"):
        if os.path.exists(path):
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    data = json.load(fh)
                for test_file in data.get("testResults", []):
                    for assertion in test_file.get("assertionResults", []):
                        name = assertion.get("fullName") or assertion.get("title")
                        status = assertion.get("status", "")
                        if not name:
                            continue
                        if status == "passed":
                            add_result(name, "pass")
                        elif status == "failed":
                            add_result(name, "fail")
                        elif status in ("skipped", "pending", "todo", "disabled"):
                            add_result(name, "skip")
            except Exception:
                pass

    # Parse jest JSON embedded in log if present
    if '"testResults"' in log:
        idx = log.rfind('"testResults"')
        if idx != -1:
            start = log.rfind('{', 0, idx)
            if start != -1:
                json_text = log[start:].strip()
                try:
                    data = json.loads(json_text)
                    for test_file in data.get("testResults", []):
                        for assertion in test_file.get("assertionResults", []):
                            name = assertion.get("fullName") or assertion.get("title")
                            status = assertion.get("status", "")
                            if not name:
                                continue
                            if status == "passed":
                                add_result(name, "pass")
                            elif status == "failed":
                                add_result(name, "fail")
                            elif status in ("skipped", "pending", "todo", "disabled"):
                                add_result(name, "skip")
                except Exception:
                    pass

    return results

