log_parser:
def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    status_priority = {"pass": 1, "skip": 2, "fail": 3}

    status_line_re = re.compile(r"---\s+(PASS|FAIL|SKIP):\s+([^\s]+)")
    plain_go_re = re.compile(r"^(?:\s*)---\s+(PASS|FAIL|SKIP):\s+([^\s]+)")

    last_pkg = None

    def record(name: str, status: str) -> None:
        if not name or status not in status_priority:
            return
        current = results.get(name)
        if current is None or status_priority[status] >= status_priority[current]:
            results[name] = status

    def handle_status_line(line: str, pkg: str | None) -> None:
        match = status_line_re.search(line) or plain_go_re.search(line)
        if not match:
            return
        status = match.group(1).lower()
        test = match.group(2)
        name = f"{pkg}/{test}" if pkg else test
        record(name, status)

    for raw_line in log.splitlines():
        line = raw_line.strip("\n")
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            # Fallback: parse raw go test output lines
            handle_status_line(line, last_pkg)
            continue

        pkg = obj.get("Package") or last_pkg
        if obj.get("Package"):
            last_pkg = obj["Package"]

        action = obj.get("Action")
        test = obj.get("Test")
        output = obj.get("Output")

        if action in ("pass", "fail", "skip") and test:
            name = f"{pkg}/{test}" if pkg else test
            record(name, action)
            continue

        if action == "output" and output:
            handle_status_line(output, pkg)

    return results

