def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def add(name: str | None, status: str) -> None:
        if not name:
            return
        if status not in {"pass", "fail", "skip"}:
            return
        results[name] = status

    def normalize_status(raw: str | None) -> str | None:
        if not raw:
            return None
        status = str(raw).lower()
        if status in {"passed", "pass", "ok", "success"}:
            return "pass"
        if status in {"failed", "fail", "error"}:
            return "fail"
        if status in {"skipped", "pending", "todo", "disabled", "omit", "ignored"}:
            return "skip"
        return None

    def compose_name(case: dict, suite_name: str) -> str:
        name = case.get("fullName") or case.get("title") or case.get("name")
        if not name:
            title = case.get("title") or case.get("name") or ""
            ancestors = case.get("ancestorTitles") or case.get("ancestors") or []
            if ancestors:
                name = " ".join([*ancestors, title]).strip()
            else:
                name = title
        if suite_name and name and not name.startswith(suite_name):
            return f"{suite_name} {name}".strip()
        return (name or suite_name).strip()

    def handle_suite(suite: dict) -> None:
        suite_name = (
            suite.get("name")
            or suite.get("testFilePath")
            or suite.get("file")
            or suite.get("suiteName")
            or ""
        )

        case_lists = []
        if isinstance(suite.get("assertionResults"), list):
            case_lists.append(suite["assertionResults"])
        if isinstance(suite.get("tests"), list):
            case_lists.append(suite["tests"])
        if isinstance(suite.get("testResults"), list):
            case_lists.append(suite["testResults"])

        for cases in case_lists:
            for case in cases:
                if not isinstance(case, dict):
                    continue
                status = normalize_status(case.get("status") or case.get("state"))
                name = compose_name(case, suite_name)
                if status:
                    add(name, status)
                else:
                    if case.get("failureMessages"):
                        add(name, "fail")

    def handle_json(data) -> None:
        if isinstance(data, dict):
            if "testResults" in data and isinstance(data["testResults"], list):
                for suite in data["testResults"]:
                    if isinstance(suite, dict):
                        handle_suite(suite)
            if "assertionResults" in data and isinstance(data["assertionResults"], list):
                handle_suite({"assertionResults": data["assertionResults"]})
            if "tests" in data and isinstance(data["tests"], list):
                handle_suite({"tests": data["tests"]})
        elif isinstance(data, list):
            for item in data:
                handle_json(item)

    def try_parse_json(text: str) -> bool:
        try:
            data = json.loads(text)
        except Exception:
            return False
        handle_json(data)
        return True

    if try_parse_json(log.strip()):
        return results

    # Try to extract JSON substrings by matching braces/brackets
    candidates = []
    for i, ch in enumerate(log):
        if ch in "{[":
            stack = [ch]
            for j in range(i + 1, len(log)):
                c = log[j]
                if c in "{[":
                    stack.append(c)
                elif c in "}]":
                    if not stack:
                        break
                    opener = stack.pop()
                    if (opener == "{" and c != "}") or (opener == "[" and c != "]"):
                        stack = []
                        break
                    if not stack:
                        candidates.append(log[i : j + 1])
                        break

    for cand in sorted(candidates, key=len, reverse=True):
        if try_parse_json(cand) and results:
            return results

    # JUnit XML parsing
    if "<testsuite" in log or "<testcase" in log:
        try:
            import xml.etree.ElementTree as ET

            m = re.search(r"<testsuites?[^>]*>", log)
            xml = log[m.start() :] if m else log
            root = ET.fromstring(xml)
            for tc in root.iter("testcase"):
                name = tc.get("name") or ""
                classname = tc.get("classname") or ""
                full = f"{classname} {name}".strip() if classname else name
                status = "pass"
                if tc.find("failure") is not None or tc.find("error") is not None:
                    status = "fail"
                elif tc.find("skipped") is not None:
                    status = "skip"
                add(full, status)
            if results:
                return results
        except Exception:
            pass

    # Fallback line parsing for common outputs
    for line in log.splitlines():
        m = re.match(r"--- (PASS|FAIL|SKIP): (.+)", line)
        if m:
            status_map = {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}
            add(m.group(2).strip(), status_map[m.group(1)])
            continue

        m = re.match(r"(.+?)::(.+?)\s+(PASSED|FAILED|SKIPPED|ERROR)", line)
        if m:
            name = f"{m.group(1)}::{m.group(2)}"
            status_map = {
                "PASSED": "pass",
                "FAILED": "fail",
                "ERROR": "fail",
                "SKIPPED": "skip",
            }
            add(name, status_map[m.group(3)])
            continue

        m = re.match(r"(\S+)\s+\(([^)]+)\)\s+\.\.\.\s+(ok|FAIL|ERROR|SKIP|skipped)", line)
        if m:
            name = f"{m.group(2)}.{m.group(1)}"
            status = m.group(3).lower()
            if status == "ok":
                add(name, "pass")
            elif status in {"skip", "skipped"}:
                add(name, "skip")
            else:
                add(name, "fail")
            continue

        m = re.match(r"\s*[✓√]\s+(.+)", line)
        if m:
            add(m.group(1).strip(), "pass")
            continue
        m = re.match(r"\s*[✕x×]\s+(.+)", line)
        if m:
            add(m.group(1).strip(), "fail")
            continue
        m = re.match(r"\s*○\s+(.+)", line)
        if m:
            add(m.group(1).strip(), "skip")
            continue

    return results

