log_parser:
def parser(log: str) -> dict[str, str]:
    import json
    from typing import Dict

    results: Dict[str, str] = {}
    decoder = json.JSONDecoder()
    idx = 0
    n = len(log)
    while idx < n:
        # find next JSON object start
        while idx < n and log[idx] != "{":
            idx += 1
        if idx >= n:
            break
        try:
            obj, end = decoder.raw_decode(log, idx)
        except json.JSONDecodeError:
            idx += 1
            continue
        idx = end
        test_results = obj.get("testResults", [])
        for suite in test_results:
            file_name = suite.get("name", "")
            for test in suite.get("assertionResults", []):
                full_name = test.get("fullName") or test.get("title") or ""
                test_name = f"{file_name}::{full_name}" if file_name else full_name
                status = test.get("status", "").lower()
                if status == "passed":
                    results[test_name] = "pass"
                elif status in ("failed", "error", "timeout", "cancelled"):
                    results[test_name] = "fail"
                elif status in ("skipped", "pending", "todo", "disabled"):
                    results[test_name] = "skip"
    return results
